H.append(f'''<section class="section_hero"><div class="hero_grafik"><img class="hero_grafik-image" src="{A('6ade29614f41302393c93236','grafik-punktemeer-hero.jpg')}" alt=""></div><div class="hero_wrap"><div class="padding-global"><div class="container-large"><div class="padding-section-large"><div class="hero_layout"><div class="hero_content"><div class="kicker"><div class="kicker_line"></div><div class="text-style-kicker">Beratung · Training · Digitale Werkzeuge</div></div><h1 class="heading-style-h1"><span class="hero_line is-muted">Mehr Vertriebsleistung.</span><span class="hero_line is-muted">Stärkere Führung.</span><span class="hero_line"><span class="hero_highlight">Weniger Fluktuation.</span></span></h1><p class="text-size-large max-width-medium">Wir entwickeln Finanzunternehmen: datenbasiert, praxiserprobt, nachhaltig.</p></div><div class="hero_media"><img class="hero_media-image" src="{A('6ade290fff14354501526916','hero-trainer-seminar.jpg')}"><div class="ribbon"></div></div></div></div></div></div></div><a class="hero_scroll" href="#loesungen"><div class="text-style-kicker">Lösungen entdecken</div><div class="hero_scroll-line"></div></a></section>''')
H.append(wrap('section_logos theme-hell','<div class="logos_label">Unter anderem vertrauen uns diese Finanzunternehmen</div><div class="logos_marquee"><div class="logos_fade is-left"></div><div class="logos_track"><div class="logos_list">'+''.join(f'<img class="logos_image" src="{A(i,n)}">' for i,n in logos)+'</div><div class="logos_list" aria-hidden="true">'+''.join(f'<img class="logos_image" src="{A(i,n)}">' for i,n in logos)+'</div></div><div class="logos_fade is-right"></div></div>','padding-section-small'))
bento=f'''<div class="bento_grid"><div class="bento_featured"><a href="#" class="card_featured w-inline-block"><div class="card_featured_content"><div class="text-style-kicker">Thema 01</div><h3 class="heading-style-h3">Vertriebsperformance</h3><p class="text-size-regular text-color-muted">Verkaufsleistung messbar steigern: von der Diagnostik über das Training bis zur Begleitung im Kundengespräch.</p></div><div class="card_featured_grafik"><img class="card_featured_image" src="{A('6ade2961405d5ecd5757d4d5','grafik-vertriebsperformance.jpg')}"></div><div class="card_featured_footer"><div class="button">Zur Vertriebsperformance</div></div></a></div>'''+feat('Thema 02','Mensch &amp; Potenzial','Potenziale sichtbar machen und gezielt entwickeln: mit Diagnostik, Coaching und Resilienz-Training.','Mehr zu Mensch &amp; Potenzial')+feat('Thema 03','Leadership &amp; Team','Führung wirksam gestalten: vom Führungsprofil bis zur Teamentwicklung.','Mehr zu Leadership &amp; Team')+feat('Thema 04','Recruiting &amp; Retention','Talente gewinnen, gut integrieren und langfristig binden: vom Assessment bis zur attraktiven Arbeitgebermarke.','Mehr zu Recruiting &amp; Retention')+feat('Thema 05','Digitale Lösungen','E-Learning, hybride Lernformate und digitale Werkzeuge, die Training und Beratung in den Alltag verlängern.','Mehr zu den digitalen Lösungen')+'</div>'
H.append(wrap('section_loesungen theme-soft','<div class="section-head_row"><div class="section-head is-flush">'+K('Was wir tun')+'<h2 class="heading-style-h2">Lösungen für Unternehmen</h2><p class="text-size-medium text-color-muted">Fünf Themen, ein abgestimmtes System: Wir stärken Vertrieb, Führung und Personal so, dass sie zusammenwirken.</p></div><a href="#" class="button is-secondary is-small">Zum Unternehmensbereich</a></div>'+bento))
H.append(wrap('section_antrieb theme-sea','<div class="statement_layout"><div class="section-head is-flush">'+K('Was uns antreibt')+'<h2 class="heading-style-h2">Messbare Entwicklung statt Versprechen.</h2></div><div class="statement_content"><p class="statement_text">Seit <span class="statement_highlight">20 Jahren</span> arbeiten wir ausschliesslich für die Finanzbranche. Wir verbinden Menschen, Methoden und Daten, damit Entwicklung kein Versprechen bleibt, sondern messbar wird.</p><div class="stats_grid"><div class="stat_item"><div class="stat_number">20</div><div class="stat_label">Jahre ausschliesslich in der Finanzbranche</div></div><div class="stat_item"><div class="stat_number">100 %</div><div class="stat_label">Praxisbezug ab dem ersten Tag</div></div><div class="stat_item"><div class="stat_number">150</div><div class="stat_label">Jahre Wissen und Erfahrung im Trainerteam</div></div></div></div></div>'))
steps=''.join(f'<div class="step_item"><div class="step_number">0{i}</div><div class="step_content"><h3 class="heading-style-h4">{t}</h3><div class="step_lead">{l}</div><p class="text-size-regular text-color-muted">{x}</p></div></div>' for i,(t,l,x) in enumerate([('Analysieren','Ist-Zustand erheben, Ziele festlegen.','Mit Diagnostik, Daten und Gesprächen erfassen wir, wo Ihr Unternehmen heute steht. Wo es sinnvoll ist, legen wir ein Soll-Profil fest: messbare Ziele, abgeleitet aus Vergleichsgruppen, auch für Soft Skills.'),('Verstehen','Muster erkennen, Ursachen verstehen.','Wir machen sichtbar, was wirkt, wo Leistung verloren geht und was die Menschen antreibt.'),('Handeln','Gezielt umsetzen, laufend nachjustieren.','Programme, Begleitung und digitale Werkzeuge setzen genau dort an.'),('Messen','Wirkung belegen, den Kreis schliessen.','Mit denselben Instrumenten wie zu Beginn messen wir, was sich verändert hat.')],1))
H.append(wrap('section_vorgehen theme-hell',f'<div class="vorgehen_layout"><div class="vorgehen_content"><div class="section-head">{K('So arbeiten wir')}<h2 class="heading-style-h2">Unser Vorgehen</h2><p class="text-size-medium text-color-muted">Vom Bauchgefühl zur Gewissheit: Jedes Projekt beginnt mit einem Erstgespräch und durchläuft dann vier Phasen.</p></div><div class="steps_list">{steps}</div><div class="steps_note">Die Messung ist zugleich der Start der nächsten Analyse. <a href="#" class="text-style-link">Mehr zu unserem Vorgehen</a></div></div><div class="vorgehen_media"><img class="vorgehen_image" src="{A("6ade2961bd3ee2a36dff2c17","grafik-vorgehen-treppe.jpg")}"></div></div>'))
tools=''.join(feat(k,t,x,f'Mehr zu {k}') for k,t,x in [('Anker','Talente finden und halten','Das Personalökosystem begleitet vom ersten Interesse bis zur Anstellung, findet die richtigen Mitarbeitenden und senkt die Fluktuation.'),('Kompass','Beratung strukturiert führen','Der digitale Beratungsprozess führt Beraterinnen und Berater Schritt für Schritt von der Ausgangslage zur passenden Lösung.'),('Lotse','Lernerfolg im Alltag sichern','Der digitale Performance Coach begleitet Entwicklung über den Trainingstag hinaus, damit das Gelernte im Alltag wirkt.'),('Segel','Beratung gemeinsam erleben','Die interaktive Beratung macht Themen im Kundengespräch sichtbar und greifbar, mit hybridem Storytelling.'),('Logbuch','Der nächste Schritt im Verkauf','Der digitale Sales Coach gibt Beraterinnen und Beratern im Alltag konkrete Impulse für das nächste Kundengespräch.')])
H.append(wrap('section_digital theme-kontrast',f'<div class="digital_intro"><div class="digital_content"><div class="section-head is-flush">{K('ROWAPA Digital')}<h2 class="heading-style-h2">Digitale Werkzeuge, die Ihren Vertrieb im Alltag begleiten</h2><p class="text-size-medium text-color-muted">Was wir beraten, bauen wir auch: Unsere Methodik steckt in fünf digitalen Werkzeugen mit künstlicher Intelligenz, entwickelt mit ETH juniors (ETH Zürich). Eingeführt werden sie vom Vertrieb oder vom HR, genutzt im ganzen Vertrieb bis zur einzelnen Beraterin und zum einzelnen Berater. Jedes Werkzeug ist einzeln buchbar.</p></div><div class="note-box"><div class="icon-box"><img class="icon-box_image" src="{C}6ade41b044ad87ca90187288_rowapa-signet-negativ.svg"></div><div class="note-box_content"><div class="note-box_title">Das Fundament: die ROWAPA Wissensplattform</div><p class="text-size-small text-color-muted">Alle fünf Werkzeuge nutzen dieselbe Wissensbasis: 20 Jahre bewährte Praxis aus Vertrieb und Führung in der Finanzbranche, laufend um externes Wissen ergänzt. Die KI arbeitet so nicht mit allgemeinem Internetwissen, sondern mit dem, was sich in der Praxis bewährt hat.</p></div></div><div class="button-group"><a href="#" class="button">Demo vereinbaren</a><a href="#" class="button is-secondary">Alle digitalen Lösungen</a></div></div><div class="digital_visual"><img class="digital_image" src="{A("6ade29617800364969057c84","grafik-wissensplattform-orbit.jpg")}"></div><div class="tools_grid">{tools}</div></div>'))
qc=lambda h,q,n,r: f'<div class="card"><div class="card_content"><h3 class="quote_headline is-small">{h}</h3><p class="quote_text is-plain">{q}</p><div class="card_footer"><div class="quote_author"><div class="person_name">{n}</div><div class="person_role">{r}</div></div></div></div></div>'
H.append(wrap('section_erfolge theme-soft',f'<div class="section-head_row"><div class="section-head is-flush">{K('Referenzen')}<h2 class="heading-style-h2">Unsere Erfolge</h2></div><a href="#" class="button is-secondary is-small">Alle Referenzen</a></div><div class="quote_featured"><div class="quote_image-wrapper"><img class="cover-image" src="{A("6ade28fdbbcf70c54b5b24f5","erfolg-raiffeisen-mittelthurgau.jpeg")}"></div><div class="quote_content"><h3 class="quote_headline">Höhere Abschlussquote, mehr Cross-Selling.</h3><p class="quote_text">«Durch die Schulungen konnten wir verschiedene qualitative Ziele erreichen: die Steigerung der Geschäftsvolumen, der Abschlussquote und der Cross- und Up-Selling-Quote.»</p><div class="quote_author"><div class="person_name">Philippe Lienhard</div><div class="person_role">Vorsitzender der Bankleitung, Raiffeisenbank Mittelthurgau</div></div></div></div><div class="layout-grid is-3-col is-erfolge">'+qc('Sehr hohe Umsetzungsquote.','«Die Seminare zeichnen sich durch einen sehr hohen Praxisbezug aus. Sie gewinnen unsere Mitarbeitenden für sich und garantieren eine sehr hohe Umsetzungsquote.»','Bernard Dietrich','Leiter Vertrieb &amp; Marketing, Basler Versicherung')+qc('Nachhaltig durch Begleitung im Alltag.','«Durch die Besuchsbegleitungen und den Einbezug der Führungskräfte wird die Nachhaltigkeit nochmals erheblich erhöht.»','Eva-Maria Süess','Mitglied der Bankleitung, Raiffeisenbank Berg-Erlen')+qc('Vier Kennzahlen massgeblich verbessert.','«Durch die Schulungen konnten wir verschiedene Zahlen massgeblich und qualitativ stark verbessern: Abschlussquote, Prämiendurchschnitt, Cross- und Up-Selling-Quote und Stornoquote.»','Adrian Künzli','Generalagent, die Mobiliar Ausserrhoden')+'</div>'))
