H.append(wrap('section_team theme-hell',f'<div class="section-head_row"><div class="section-head is-flush">{K('Über uns')}<h2 class="heading-style-h2">Die Menschen hinter ROWAPA</h2></div><a href="#" class="button is-secondary is-small">Team kennenlernen</a></div><div class="team_grid">{tm}</div><div class="partner_block"><div class="section-head is-flush">{K('Partner und Zertifizierungen')}<p class="text-size-regular text-color-muted">Verankert in der Branche: akademische Partner, Verbände und Technologiepartner.</p></div><div class="logos_grid is-partner">'+''.join(f'<img class="logos_image is-cell" src="{A(i,n)}">' for i,n in partners)+'</div></div>'))
H.append(wrap('section_wege theme-sea','<div class="section-head">'+K('Meine Entwicklung')+'<h2 class="heading-style-h2">Persönlich weiterkommen</h2><p class="text-size-medium text-color-muted">Drei Wege für Menschen in der Finanzbranche, die sich selbst weiterentwickeln wollen.</p></div><div class="layout-grid is-3-col">'+teaser(A('6ade2900b26de708a91dc5cf','weg-privatpersonen.jpg'),'Privatpersonen','Für Einzelpersonen','Persönliche Entwicklung','Diagnostik, Weiterbildung und Coaching für ambitionierte Profis, vom Einstieg bis zur Führungsrolle.','Passenden Weg finden',C+'6ade408a27cf9de2fe4bdccf_video-weg-privatpersonen.mp4')+teaser(A('6ade2903e7abdfa0c1782fa7','weg-broker-excellence.jpg'),'Fokusprogramm','Für Broker und Brokerfirmen','Broker Excellence','Aus- und Weiterbildung für den Broker-Markt: für einzelne Broker und ganze Brokerfirmen.','Zu Broker Excellence',C+'6ade41b0ab3cad773e91fbff_video-weg-broker.mp4')+teaser(A('6ade29083afeca34a032edf2','weg-female-empowerment.jpg'),'Fokusprogramm','Für Frauen in der Finanzbranche','Female Empowerment','Souverän auftreten, verhandeln und führen: mit dem Programm SOUVERÄN ICH und einer starken Community.','Zu Female Empowerment',C+'6ade41b0d618ef3b9679b690_video-weg-female.mp4')+'</div>'))
H.append(wrap('section_cas theme-tiefsee',f'<div class="spotlight_layout"><div class="spotlight_content">{K('Im Blickpunkt')}<h2 class="heading-style-h2">CAS Professional Leadership for Finance</h2><p class="text-size-medium text-color-muted">Der erste CAS-Lehrgang (Certificate of Advanced Studies), der zusammen mit der HWZ Hochschule für Wirtschaft Zürich exklusiv für die Finanzbranche entwickelt wurde. Führungsthemen aus dem Berufsalltag, mit Dozierenden und Gastreferierenden aus der Praxis.</p><div class="chip-list"><div class="chip">Start 25. Februar 2027</div><div class="chip">16 Präsenztage</div><div class="chip">15 ECTS-Punkte</div><div class="chip">mit der HWZ Zürich</div></div><div class="button-group"><a href="#" class="button">Mehr zum CAS</a><a href="#" class="button is-secondary">Zoom-Infosession am 17.11.2026</a></div></div><div class="spotlight_media"><img class="cover-image" src="{A("6ade290b9d6c402cfe66af48","cas-abschlussfeier-hwz.jpeg")}"></div></div>'))
H.append(wrap('section_insights theme-soft','<div class="section-head_row"><div class="section-head is-flush">'+K('Wissen &amp; Impulse')+'<h2 class="heading-style-h2">Neueste Insights</h2></div><a href="#" class="button is-secondary is-small">Alle Inhalte</a></div><div class="layout-grid is-3-col">'+teaser(A('6ade29218744271fad9ac386','blog-zeitmanagement-im-vertrieb.jpeg'),'Sales','23.09.2025 · Blog','Zeitmanagement im Vertrieb','Warum zu viel Eifer die eigenen Ziele sabotieren kann, und drei Prinzipien für mehr Zeit im Kundengespräch.','Beitrag lesen')+teaser(A('6ade29243afeca34a032f10f','blog-leadership-weiterbildung.jpeg'),'Leadership','26.08.2025 · Blog','Leadership-Weiterbildung','Woran sich erkennen lässt, ob jetzt der richtige Zeitpunkt für eine Führungsweiterbildung ist.','Beitrag lesen')+'<div class="grid-item_hide-mobile">'+teaser(A('6ade29279a21a1e2cc4cd1ed','blog-empathische-fuehrung.jpeg'),'Leadership','25.08.2025 · Blog','Empathische Führung','Was Mitarbeitende wirklich an ein Unternehmen bindet, und welche Rolle Führung dabei spielt.','Beitrag lesen')+'</div>'+'</div><div class="link-teaser-list"><a href="#" class="link-teaser w-inline-block"><div class="link-teaser_content"><div class="note-box_title">Live-Webinare</div><div class="text-size-small text-color-muted">Kostenlos teilnehmen, alle Termine im Überblick.</div></div><div class="icon-box">→</div></a><a href="#" class="link-teaser w-inline-block"><div class="link-teaser_content"><div class="note-box_title">ROWAPA TV</div><div class="text-size-small text-color-muted">Kurze Videos mit Expertentipps und Praxiseinblicken.</div></div><div class="icon-box">→</div></a></div>'))
